def is_valid_ipv4(s: str) -> bool:
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit():
            return False
        if part.startswith('0') and len(part) > 1:
            return False
        if int(part) < 0 or int(part) > 255:
            return False
    return True
